package com.warehouse.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="items") public class Item { @Id @GeneratedValue public UUID id; @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String sku; @Column(unique=true) public String barcode; public String category; public String unit="each"; @Column(nullable=false) public int quantity; @Column(name="low_stock_threshold",nullable=false) public int lowStockThreshold; @Column(name="created_at") public Instant createdAt=Instant.now(); @Column(name="updated_at") public Instant updatedAt=Instant.now(); }
